void require(bool v,const char*m){if(!v)throw std::runtime_error(m);}
engine::core::RunStopHandle current;int target=-1;size_t trigger=1,counts[2]{},transfers[10]{},fixtures=0;bool bad=false;
std::atomic<bool>gate{false},entered{false},release_gate{false},returned{false},expired{false};std::atomic<size_t>active{0};std::mutex mutex;std::condition_variable cv;std::vector<int>trace;
void reset(){current=std::make_shared<engine::core::RunStopState>();target=-1;trigger=1;counts[0]=counts[1]=0;for(auto&v:transfers)v=0;bad=false;gate=false;entered=false;release_gate=false;returned=false;expired=false;active=0;trace.clear();}
void hit(int phase,size_t amount){++active;trace.push_back(phase);if(target==phase&&amount>=trigger){if(gate&&!entered.exchange(true)){cv.notify_all();std::unique_lock<std::mutex>l(mutex);if(!cv.wait_for(l,std::chrono::seconds(2),[]{return release_gate.load();})){expired=true;release_gate=true;}}else if(!gate)current->cancel();}--active;}
struct Tensors{
 ggml_context*ctx=nullptr;ggml_backend_t backend=nullptr;ggml_backend_buffer_t buffer=nullptr;
 engine::core::TensorValue token,position,slot,mask;ggml_tensor*guard=nullptr;
 Tensors(int heads,int cache){ctx=ggml_init({1048576,nullptr,true});backend=ggml_backend_cpu_init();require(ctx&&backend,"actual CPU resources");auto make=[&](ggml_type type,std::initializer_list<int64_t>dims){engine::core::TensorValue v;v.type=type;v.shape=engine::core::TensorShape::from_dims(dims);std::array<int64_t,4>ne{1,1,1,1};for(size_t j=0;j<v.shape.rank;++j)ne[j]=v.shape.dims[v.shape.rank-j-1];v.tensor=ggml_new_tensor(ctx,type,int(v.shape.rank),ne.data());return v;};token=make(GGML_TYPE_I32,{1});position=make(GGML_TYPE_I32,{1});slot=make(GGML_TYPE_I32,{1});mask=make(GGML_TYPE_F16,{1,heads,1,cache});guard=ggml_new_tensor_1d(ctx,GGML_TYPE_I32,7);buffer=ggml_backend_alloc_ctx_tensors(ctx,backend);require(buffer,"real tensor allocation");ggml_backend_buffer_clear(buffer,0x55);int32_t canary[7]={11,22,33,44,55,66,77};ggml_backend_tensor_set(guard,canary,0,sizeof canary);}
 ~Tensors(){if(buffer)ggml_backend_buffer_free(buffer);if(ctx)ggml_free(ctx);if(backend)ggml_backend_free(backend);}
 std::vector<ggml_fp16_t> read_mask(){std::vector<ggml_fp16_t>v(size_t(ggml_nelements(mask.tensor)));ggml_backend_tensor_get(mask.tensor,v.data(),0,v.size()*sizeof(ggml_fp16_t));return v;}
 void check_ids(int token_value,int end,int valid){int32_t ids[3];ggml_backend_tensor_get(token.tensor,&ids[0],0,4);ggml_backend_tensor_get(position.tensor,&ids[1],0,4);ggml_backend_tensor_get(slot.tensor,&ids[2],0,4);require(ids[0]==token_value&&ids[1]==end+2&&ids[2]==valid,"actual I32 token+2position/slot");int32_t canary[7];ggml_backend_tensor_get(guard,canary,0,sizeof canary);for(int i=0;i<7;++i)require(canary[i]==11*(i+1),"tensor canary untouched");}
};
void same(const std::vector<ggml_fp16_t>&a,const std::vector<ggml_fp16_t>&b){require(a==b,"exact F16 bits parity");}
unsigned long long hash(const std::vector<ggml_fp16_t>&v){unsigned long long h=1469598103934665603ull;for(auto x:v)h=(h^x)*1099511628211ull;return h;}
void step(const ss::SheetSage2DecoderConfig&c,int cache,int valid,int end,std::vector<ggml_fp16_t>&v,Tensors&t){ss::stage_decoder_step(c,1,cache,valid,end,17,v,t.token,t.position,t.slot,t.mask,current);}
void product_cases(){for(size_t bytes:{size_t(2),size_t(4)})for(bool reversed:{false,true}){bool ordinary=false;try{if(reversed)ss::decoder_product({128,INT64_MAX},bytes);else ss::decoder_product({INT64_MAX,128},bytes);}catch(const std::runtime_error&){ordinary=true;}require(ordinary,"bounded arithmetic-only checked product before allocation");++fixtures;}}
void parity(){size_t golden_index=0;const unsigned long long golden[]={0x47fe0d7eaf8e51e3ull,0x47fe0d7eaf8e51e3ull,0x47fe0d7eaf8e51e3ull,0xbc265913fcc9daa3ull,0xd95032fe2163caa3ull,0x8e23ad2c8bb902a3ull,0xbe9546038f146ce3ull,0x2c7c6a45efdf44e3ull,0xff32cb12a2c8d4e3ull,0x306c537b2ff38983ull,0x306c537b2ff38983ull,0x306c537b2ff38983ull,0x9749d4d7d2855583ull,0x215b5c218371b583ull,0x555e0e7f0688f583ull,0x5ab116ab2e182983ull,0x437cb65de297c983ull,0xd58926384b52183ull};for(int heads:{8,128})for(int cache:{1,3,9})for(int valid:{0,cache/2,cache-1}){ss::SheetSage2DecoderConfig c;c.num_attention_heads=heads;Tensors t(heads,cache);for(bool owned:{false,true}){reset();auto handle=owned?current:engine::core::RunStopHandle{};std::vector<ggml_fp16_t>v;ss::reset_decoder_mask(c,1,cache,v,t.mask,handle);for(auto x:v)require(x==0xfc00,"reset exact half negative infinity");same(v,t.read_mask());ss::stage_decoder_step(c,1,cache,valid,valid,17,v,t.token,t.position,t.slot,t.mask,handle);t.check_ids(17,valid,valid);for(int h=0;h<heads;++h)for(int slot=0;slot<cache;++slot)require(v[size_t(h)*cache+slot]==(slot==valid?0x0000:0xfc00),"head/cache axes untouched future infinity +0");same(v,t.read_mask());require(golden_index<18&&hash(v)==golden[golden_index],"pre-edit actual ID/mask frozen hash");require(!bad,"actual mask stores values");++fixtures;}++golden_index;}}
void existing_columns(){ss::SheetSage2DecoderConfig c;Tensors t(8,9);std::vector<ggml_fp16_t>v(72,0xfc00);for(int h=0;h<8;++h)for(int col=0;col<3;++col)v[size_t(h)*9+col]=0;auto before=v;reset();step(c,9,3,3,v,t);for(int h=0;h<8;++h)before[size_t(h)*9+3]=0;same(v,before);same(v,t.read_mask());t.check_ids(17,3,3);++fixtures;}
void cancel_reset(){ss::SheetSage2DecoderConfig c;Tensors t(8,9);for(size_t at:{1,64,72}){reset();target=0;trigger=at;std::vector<ggml_fp16_t>v{0x1234};bool caught=false;try{ss::reset_decoder_mask(c,1,9,v,t.mask,current);}catch(const engine::runtime::RunCancelled&){caught=true;}require(caught&&counts[0]>0&&counts[0]<=((at+63)/64)*64&&counts[0]<=72,"reset actual stores64 bound");require(v==std::vector<ggml_fp16_t>{0x1234}&&transfers[0]==0&&transfers[8]==0&&active==0&&!bad,"cancelled reset no publication/upload");auto old=current;reset();ss::reset_decoder_mask(c,1,9,v,t.mask,current);same(v,t.read_mask());require(old->cancelled()&&!current->cancelled(),"reset A then fresh B");fixtures+=2;}
 for(int phase:{10,11,21,27}){reset();target=phase;std::vector<ggml_fp16_t>v{0x1234};bool caught=false;try{ss::reset_decoder_mask(c,1,9,v,t.mask,current);}catch(const engine::runtime::RunCancelled&){caught=true;}require(caught&&v==std::vector<ggml_fp16_t>{0x1234}&&active==0,"reset transfer/final publication cancellation");require(trace.back()==phase,"no phase after reset observation");++fixtures;}}
void cancel_step(){for(int heads:{8,128}){ss::SheetSage2DecoderConfig c;c.num_attention_heads=heads;Tensors t(heads,3);std::vector<ggml_fp16_t>v(size_t(heads)*3,0xfc00);for(size_t at:(heads==8?std::vector<size_t>{1,8}:std::vector<size_t>{1,64,128})){reset();v.assign(v.size(),0xfc00);target=1;trigger=at;bool caught=false;try{step(c,3,1,1,v,t);}catch(const engine::runtime::RunCancelled&){caught=true;}require(caught&&counts[1]>0&&counts[1]<=((at+63)/64)*64&&counts[1]<=size_t(heads)&&active==0&&!bad,"step actual head stores64 bound");require(transfers[4]==0&&transfers[8]==0,"stopped short/full head tile never publishes");auto old=current;reset();v.assign(v.size(),0xfc00);step(c,3,1,1,v,t);same(v,t.read_mask());t.check_ids(17,1,1);require(old->cancelled()&&!current->cancelled(),"step fresh B full parity");fixtures+=2;}
 for(int stage:{1,2,3,4,6,8})for(bool after:{false,true}){if(stage==6&&after)continue;if(stage==8&&!after)continue;reset();target=10+2*stage+int(after);v.assign(v.size(),0xfc00);bool caught=false;try{step(c,3,1,1,v,t);}catch(const engine::runtime::RunCancelled&){caught=true;}require(caught&&active==0&&!bad,"step boundary cancellation settled");require(trace.back()==target,"no later stage after boundary stop");if(stage<=4)require(transfers[stage]==size_t(after),"actual transfer before-after counts");++fixtures;}
 }}
void validation(){for(bool stopped:{false,true})for(int k=0;k<17;++k){reset();if(stopped)current->cancel();ss::SheetSage2DecoderConfig c;int64_t memory=1,cache=3,valid=0,end=0;int32_t token=17;size_t count=24;if(k==0)memory=INT64_MAX;if(k==1)cache=0;if(k==2)c.num_attention_heads=0;if(k==3)c.num_attention_heads=3;if(k==4)c.hidden_size=0;if(k==5)c.decoder_layers=INT64_MAX;if(k==6)c.vocab_size=0;if(k==7)c.max_position_embeddings=INT64_MAX;if(k==8)token=-1;if(k==9)token=int(c.vocab_size);if(k==10)valid=-1;if(k==11)valid=3;if(k==12)end=-1;if(k==13)end=c.max_position_embeddings;if(k==14)end=INT64_MAX;if(k==15)count=23;if(k==16)cache=c.max_position_embeddings+1;bool ordinary=false;try{ss::decoder_step_validate(c,memory,cache,valid,end,token,count);ss::encoder_stop(current);}catch(const engine::runtime::RunCancelled&){ordinary=false;}catch(const std::runtime_error&){ordinary=true;}require(ordinary&&trace.empty(),"D1 ordinary invalid before stop/transfers");++fixtures;}
 ss::SheetSage2DecoderConfig c;for(bool stopped:{false,true})for(int k=0;k<4;++k){reset();if(stopped)current->cancel();std::vector<int32_t>prefix{1,2};int64_t valid=2,end=2;if(k==0)prefix={};if(k==1){prefix={1,-1};valid=0;end=0;}if(k==2)prefix={1,2};if(k==3){prefix={1,2};valid=0;end=c.max_position_embeddings-1;}bool ordinary=false;try{ss::decoder_prefix_validate(c,1,3,valid,end,prefix,24);ss::encoder_stop(current);}catch(const engine::runtime::RunCancelled&){ordinary=false;}catch(const std::runtime_error&){ordinary=true;}require(ordinary&&trace.empty(),"prefix invalid final token/remaining capacity/position preflight");++fixtures;}
 ss::decoder_step_validate(c,1,3,2,c.max_position_embeddings-1,17,24);ss::decoder_prefix_validate(c,1,3,1,1,{17,18},24);fixtures+=2;
}
void focused_postcancel_B(){ss::SheetSage2DecoderConfig c;Tensors t(8,3);reset();target=0;std::vector<ggml_fp16_t>cancelled;bool caught=false;try{ss::reset_decoder_mask(c,1,3,cancelled,t.mask,current);}catch(const engine::runtime::RunCancelled&){caught=true;}require(caught&&active==0,"focused A cancelled and settled");auto actual_a=current;reset();auto actual_b=current;std::vector<ggml_fp16_t>b;bool fresh_completed=false;try{ss::reset_decoder_mask(c,1,3,b,t.mask,actual_b);step(c,3,1,1,b,t);fresh_completed=true;}catch(const engine::runtime::RunCancelled&){}require(fresh_completed,"focused postcancel B must complete on distinct handle");require(actual_a->cancelled()&&!actual_b->cancelled(),"focused postcancel B fresh identity");for(int h=0;h<8;++h)for(int col=0;col<3;++col)require(b[size_t(h)*3+col]==(col==1?0:0xfc00),"focused postcancel B complete independent parity");same(b,t.read_mask());t.check_ids(17,1,1);++fixtures;}
void malformed_staging(){ss::SheetSage2DecoderConfig c;Tensors t(8,3);for(bool stopped:{false,true})for(int k=0;k<4;++k){reset();if(stopped)current->cancel();auto token=t.token;auto mask=t.mask;std::vector<ggml_fp16_t>v(24,0xfc00);if(k==0)token.type=GGML_TYPE_F16;if(k==1)token.tensor=nullptr;if(k==2)mask.shape.dims[1]=INT64_MAX;if(k==3)v.pop_back();bool ordinary=false;try{ss::stage_decoder_step(c,1,3,1,1,17,v,token,t.position,t.slot,mask,current);}catch(const engine::runtime::RunCancelled&){ordinary=false;}catch(const std::runtime_error&){ordinary=true;}require(ordinary&&trace.empty(),"actual malformed staging ordinary error before prestop");++fixtures;}
 reset();current->cancel();std::vector<ggml_fp16_t>v(24,0xfc00);bool caught=false;try{step(c,3,1,1,v,t);}catch(const engine::runtime::RunCancelled&){caught=true;}require(caught&&trace.size()==1&&counts[0]+counts[1]==0,"valid prestop no actual stores/transfers");++fixtures;
}
void classifier(){engine::core::BackendConfig cfg;engine::core::ExecutionContext execution(cfg);for(bool stopped:{false,true})for(auto status:{GGML_STATUS_SUCCESS,GGML_STATUS_ABORTED,GGML_STATUS_FAILED,GGML_STATUS_ALLOC_FAILED}){reset();auto binding=execution.begin_cancellable_run(current);if(stopped)current->cancel();int outcome=0;try{ss::check_graph_status(status,execution,"decoder ordinary failure");}catch(const engine::runtime::RunCancelled&){outcome=1;}catch(const std::runtime_error&e){require(std::string(e.what())=="decoder ordinary failure","ordinary failure identity");outcome=2;}require(outcome==(status==GGML_STATUS_ABORTED?1:(status!=GGML_STATUS_SUCCESS?2:(stopped?1:0))),"actual authoritative status classifier");++fixtures;}}
void external(){for(bool resetting:{true,false})for(size_t at:{1,64,72}){ss::SheetSage2DecoderConfig c;c.num_attention_heads=resetting?8:128;Tensors t(int(c.num_attention_heads),resetting?9:3);int cache=resetting?9:3;reset();target=resetting?0:1;trigger=at;gate=true;std::vector<ggml_fp16_t>v(size_t(c.num_attention_heads)*cache,0xfc00);bool caught=false;std::thread owner([&]{try{if(resetting)ss::reset_decoder_mask(c,1,cache,v,t.mask,current);else step(c,cache,1,1,v,t);}catch(const engine::runtime::RunCancelled&){caught=true;}returned=true;cv.notify_all();});bool reached=false,early=false;{std::unique_lock<std::mutex>l(mutex);reached=cv.wait_for(l,std::chrono::seconds(2),[]{return entered.load()||returned.load();})&&entered;early=returned;current->cancel();release_gate=true;cv.notify_all();}owner.join();require(reached&&!early&&!expired&&caught&&active==0&&!bad,"gated mask observer settled before owner translation");size_t actual=counts[resetting?0:1];require(actual>=at&&actual-at<=63,"external residual <=64 actual stores");++fixtures;}
 for(bool resetting:{true,false})for(int phase:(resetting?std::vector<int>{10,11,21,27}:std::vector<int>{12,13,14,15,16,17,18,19,22,27})){ss::SheetSage2DecoderConfig cfg;Tensors tensors(8,9);reset();target=phase;gate=true;bool caught=false;std::vector<ggml_fp16_t>values(72,0xfc00);std::thread worker([&]{try{if(resetting)ss::reset_decoder_mask(cfg,1,9,values,tensors.mask,current);else step(cfg,9,3,3,values,tensors);}catch(const engine::runtime::RunCancelled&){caught=true;}returned=true;cv.notify_all();});bool reached=false,early=false;{std::unique_lock<std::mutex>l(mutex);reached=cv.wait_for(l,std::chrono::seconds(2),[]{return entered.load()||returned.load();})&&entered;early=returned;current->cancel();release_gate=true;cv.notify_all();}worker.join();require(reached&&!early&&!expired&&caught&&active==0,"actual reset/ID/mask/publication boundary gated settlement");require(trace.back()==phase,"gated cancel permits no later phase");++fixtures;}
 ss::SheetSage2DecoderConfig c;Tensors t(8,9);reset();auto actual_a=current;std::vector<ggml_fp16_t>a;ss::reset_decoder_mask(c,1,9,a,t.mask,actual_a);require(!actual_a->cancelled(),"actual A completed clear");reset();auto actual_b=current;target=0;gate=true;std::vector<ggml_fp16_t>b;std::thread owner([&]{ss::reset_decoder_mask(c,1,9,b,t.mask,actual_b);returned=true;cv.notify_all();});bool reached=false;{std::unique_lock<std::mutex>l(mutex);reached=cv.wait_for(l,std::chrono::seconds(2),[]{return entered.load()||returned.load();})&&entered;if(reached)actual_a->cancel();release_gate=true;cv.notify_all();}owner.join();require(reached&&actual_a!=actual_b&&actual_a->cancelled()&&!actual_b->cancelled()&&!expired,"former actual A transition while B real stores");same(a,b);same(b,t.read_mask());++fixtures;
}
