namespace engine::models::sheetsage {namespace {namespace decoder_host_testing{
void stored(bool reset,size_t index,ggml_fp16_t value)noexcept{if(reset&&index!=counts[0])bad=true;if(value!=(reset?0xfc00:0x0000))bad=true;++counts[reset?0:1];hit(reset?0:1,counts[reset?0:1]);}
void phase(int stage,bool after)noexcept{if(after)++transfers[stage];hit(10+2*stage+int(after),1);}
}}}
int main(int argc,char**argv){try{if(argc>1&&std::string(argv[1])=="postcancel-B"){focused_postcancel_B();std::cout<<"PASS focused_postcancel_B\n";return 0;}product_cases();size_t n=fixtures;parity();existing_columns();std::cout<<"parity="<<fixtures-n<<"\n";n=fixtures;cancel_reset();cancel_step();std::cout<<"cancel_reuse="<<fixtures-n<<"\n";n=fixtures;validation();malformed_staging();classifier();focused_postcancel_B();std::cout<<"validation="<<fixtures-n<<"\n";n=fixtures;external();std::cout<<"external_lateA="<<fixtures-n<<"\n";std::cout<<"PASS fixtures="<<fixtures<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
